//! Differential test: `py_url` and `legacy_fragment_target` against Creference 3.14 rows.
//!
//! Fixture: `fixtures/py_url_oracle.json`, generated by the reference suite with the oracle venv.

use serde_json::Value;
use spiderhead_parse::fragment_target::legacy_fragment_target;
use spiderhead_parse::py_url::{
    parse_qsl, quote_plus, unquote, urlencode, urljoin, urlparse, urlsplit, urlunparse, UrlError,
};

const FIXTURE: &str = include_str!("fixtures/py_url_oracle.json");

fn section(name: &str) -> Vec<Value> {
    let root: Value = serde_json::from_str(FIXTURE).unwrap_or(Value::Null);
    root.get(name)
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default()
}

fn text<'a>(row: &'a Value, key: &str) -> &'a str {
    row.get(key).and_then(Value::as_str).unwrap_or_default()
}

fn is_err(row: &Value) -> bool {
    row.get("err").and_then(Value::as_bool).unwrap_or(false)
}

#[test]
fn urlsplit_matches_cpython() {
    let rows = section("urlsplit");
    assert!(!rows.is_empty());
    let mut mismatches = Vec::new();
    for row in &rows {
        let input = text(row, "input");
        match urlsplit(input) {
            Err(UrlError::InvalidIpv6) => {
                if !is_err(row) {
                    mismatches.push(format!("{input:?}: unexpected error"));
                }
            }
            Ok(parts) => {
                let got = [
                    parts.scheme,
                    parts.netloc,
                    parts.path,
                    parts.query,
                    parts.fragment,
                ];
                let want = ["scheme", "netloc", "path", "query", "fragment"];
                for (key, value) in want.iter().zip(got.iter()) {
                    if text(row, key) != value {
                        mismatches.push(format!("{input:?} {key}: {value:?}"));
                    }
                }
            }
        }
    }
    assert!(mismatches.is_empty(), "{mismatches:#?}");
}

#[test]
fn urlparse_and_unparse_match_cpython() {
    let mut mismatches = Vec::new();
    for row in section("urlparse") {
        let input = text(&row, "input");
        let Ok(parts) = urlparse(input) else {
            if !is_err(&row) {
                mismatches.push(format!("{input:?}: unexpected error"));
            }
            continue;
        };
        let got = [
            ("scheme", parts.scheme.clone()),
            ("netloc", parts.netloc.clone()),
            ("path", parts.path.clone()),
            ("params", parts.params.clone()),
            ("query", parts.query.clone()),
            ("fragment", parts.fragment.clone()),
            ("unparse", urlunparse(&parts)),
        ];
        for (key, value) in got {
            if text(&row, key) != value {
                mismatches.push(format!("{input:?} {key}: {value:?}"));
            }
        }
    }
    assert!(mismatches.is_empty(), "{mismatches:#?}");
}

#[test]
fn urljoin_matches_cpython() {
    let mut mismatches = Vec::new();
    for row in section("urljoin") {
        let (base, url) = (text(&row, "base"), text(&row, "url"));
        match urljoin(base, url) {
            Ok(out) if out == text(&row, "out") => {}
            other => mismatches.push(format!("{base:?} + {url:?} -> {other:?}")),
        }
    }
    assert!(mismatches.is_empty(), "{mismatches:#?}");
}

#[test]
fn parse_qsl_unquote_and_quote_match_cpython() {
    let mut mismatches = Vec::new();
    for row in section("parse_qsl") {
        let input = text(&row, "input");
        let want: Vec<(String, String)> = row
            .get("out")
            .and_then(Value::as_array)
            .map(|pairs| {
                pairs
                    .iter()
                    .filter_map(|pair| {
                        let items = pair.as_array()?;
                        Some((
                            items.first()?.as_str()?.to_owned(),
                            items.get(1)?.as_str()?.to_owned(),
                        ))
                    })
                    .collect()
            })
            .unwrap_or_default();
        if parse_qsl(input) != want {
            mismatches.push(format!("parse_qsl {input:?}"));
        }
    }
    for row in section("unquote") {
        let input = text(&row, "input");
        if unquote(input) != text(&row, "out") {
            mismatches.push(format!("unquote {input:?}"));
        }
    }
    for row in section("quote_plus") {
        let input = text(&row, "input");
        if quote_plus(input) != text(&row, "out") {
            mismatches.push(format!("quote_plus {input:?}"));
        }
    }
    for row in section("urlencode") {
        let pairs: Vec<(String, String)> = row
            .get("pairs")
            .and_then(Value::as_array)
            .map(|pairs| {
                pairs
                    .iter()
                    .filter_map(|pair| {
                        let items = pair.as_array()?;
                        Some((
                            items.first()?.as_str()?.to_owned(),
                            items.get(1)?.as_str()?.to_owned(),
                        ))
                    })
                    .collect()
            })
            .unwrap_or_default();
        if urlencode(&pairs) != text(&row, "out") {
            mismatches.push(format!("urlencode {pairs:?}"));
        }
    }
    assert!(mismatches.is_empty(), "{mismatches:#?}");
}

#[test]
fn fragment_target_matches_the_oracle_rows() {
    let rows = section("fragment_target");
    assert!(rows.len() >= 300, "fixture too small: {}", rows.len());
    let mut mismatches = Vec::new();
    for row in &rows {
        let (url, html) = (text(row, "url"), text(row, "html"));
        match legacy_fragment_target(url, html) {
            Ok(got) => {
                let want = row.get("out").and_then(Value::as_str).map(str::to_owned);
                if got != want {
                    mismatches.push(format!("{url:?} / {html:?}: got {got:?}, want {want:?}"));
                }
            }
            Err(_) => {
                if !is_err(row) {
                    mismatches.push(format!("{url:?} / {html:?}: unexpected error"));
                }
            }
        }
    }
    assert!(
        mismatches.is_empty(),
        "{} mismatches:\n{mismatches:#?}",
        mismatches.len()
    );
}
